class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = {}
        score = 0
        for i, c in enumerate(s):
            mirror = chr(ord('a') + ord('z') - ord(c))
            if mirror in stacks and stacks[mirror]:
                j = stacks[mirror].pop()
                score += i - j
            else:
                if c not in stacks:
                    stacks[c] = []
                stacks[c].append(i)
        return score

from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG = float('-inf')
        # dp[i][j][k] = max coins reaching (i,j) having neutralized k cells
        dp = [[[NEG] * 3 for _ in range(n)] for _ in range(m)]
        dp[0][0][0] = coins[0][0]
        dp[0][0][1] = 0  # neutralize starting cell

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                for k in range(3):
                    # Option 1: do not neutralize current cell
                    best = NEG
                    if i > 0:
                        best = max(best, dp[i-1][j][k])
                    if j > 0:
                        best = max(best, dp[i][j-1][k])
                    if best != NEG:
                        dp[i][j][k] = max(dp[i][j][k], best + coins[i][j])
                    # Option 2: neutralize current cell (only if k >= 1)
                    if k > 0:
                        best2 = NEG
                        if i > 0:
                            best2 = max(best2, dp[i-1][j][k-1])
                        if j > 0:
                            best2 = max(best2, dp[i][j-1][k-1])
                        if best2 != NEG:
                            dp[i][j][k] = max(dp[i][j][k], best2)

        return max(dp[m-1][n-1])

from typing import List

class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        nums = sorted(nums)

        # Precompute factorials and inverse factorials
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i-1] * i % MOD
        inv_fact = [1] * (n + 1)
        inv_fact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n - 1, -1, -1):
            inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a-b] % MOD

        ans = 0
        for i in range(n):
            # nums[i] as max: pick 0..k-1 elements from i smaller ones
            cnt_max = 0
            for j in range(min(k-1, i) + 1):
                cnt_max = (cnt_max + comb(i, j)) % MOD
            # nums[i] as min: pick 0..k-1 elements from n-i-1 larger ones
            cnt_min = 0
            for j in range(min(k-1, n-i-1) + 1):
                cnt_min = (cnt_min + comb(n-i-1, j)) % MOD
            ans = (ans + nums[i] * (cnt_max + cnt_min)) % MOD

        return ans

from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        MAXV = 300
        # dp[v][d] = longest subseq (length >= 2) ending at value v with last absolute diff exactly d
        dp = [[0] * (MAXV + 1) for _ in range(MAXV + 1)]
        # suf[v][d] = max over d' >= d of dp[v][d']
        suf = [[0] * (MAXV + 1) for _ in range(MAXV + 1)]
        seen = [False] * (MAXV + 2)
        ans = 1  # at least one element

        for u in nums:
            new_dp_u = [0] * (MAXV + 1)

            # d = 0: previous value must equal u
            if seen[u]:
                best = 2
                if suf[u][0] > 0:
                    c = suf[u][0] + 1
                    if c > best:
                        best = c
                new_dp_u[0] = best
                if best > ans:
                    ans = best

            # d > 0: previous value is u-d or u+d
            for d in range(1, MAXV + 1):
                best = 0
                v1 = u - d
                if v1 >= 1 and seen[v1]:
                    best = 2
                    s = suf[v1][d]
                    if s > 0 and s + 1 > best:
                        best = s + 1
                v2 = u + d
                if v2 <= MAXV and seen[v2]:
                    if 2 > best:
                        best = 2
                    s = suf[v2][d]
                    if s > 0 and s + 1 > best:
                        best = s + 1
                if best > 0:
                    new_dp_u[d] = best
                    if best > ans:
                        ans = best

            # merge new_dp_u into dp[u]
            dp_u = dp[u]
            for d in range(MAXV + 1):
                if new_dp_u[d] > dp_u[d]:
                    dp_u[d] = new_dp_u[d]

            # recompute suffix max for u
            suf_u = suf[u]
            cur = 0
            for d in range(MAXV, -1, -1):
                if dp_u[d] > cur:
                    cur = dp_u[d]
                suf_u[d] = cur

            seen[u] = True

        return ans

import heapq
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build reverse graph
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            # original: a -> b; reversed: b -> a
            radj[b].append((a, w))

        # Dijkstra-like: minimize the maximum edge weight on path from 0
        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]  # (max_weight_on_path, node)

        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in radj[u]:
                nd = w if w > d else d
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

        ans = 0
        for i in range(n):
            if dist[i] == INF:
                return -1
            if dist[i] > ans:
                ans = dist[i]
        return ans if ans > 0 else (0 if n == 1 else ans)

class Solution:
    def countMentions(self, numberOfUsers, events):
        # Sort events by timestamp; at same timestamp, process OFFLINE before MESSAGE
        sorted_events = sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        offline_until = [0] * numberOfUsers  # user i is online iff offline_until[i] <= current time
        mentions = [0] * numberOfUsers

        for event in sorted_events:
            kind = event[0]
            t = int(event[1])
            if kind == "OFFLINE":
                uid = int(event[2])
                offline_until[uid] = t + 60
            else:  # MESSAGE
                tokens = event[2].split()
                if tokens[0] == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif tokens[0] == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= t:
                            mentions[i] += 1
                else:
                    for tok in tokens:
                        uid = int(tok[2:])  # strip "id" prefix
                        mentions[uid] += 1
        return mentions

from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        NEG = float('-inf')
        # dp[i][j] = max sum using first i elements with exactly j non-overlapping subarrays,
        # where the j-th subarray (if any) ends at or before position i.
        dp = [[NEG] * (k + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = 0

        for j in range(1, k + 1):
            # best = max over valid t (t <= i - m) of (dp[t][j-1] - prefix[t])
            best = NEG
            for i in range(1, n + 1):
                t = i - m
                if t >= 0 and dp[t][j - 1] != NEG:
                    cand = dp[t][j - 1] - prefix[t]
                    if cand > best:
                        best = cand

                # Option 1: don't end a subarray exactly at position i
                dp[i][j] = dp[i - 1][j]
                # Option 2: end a subarray of length >= m at position i
                if best != NEG:
                    val = best + prefix[i]
                    if val > dp[i][j]:
                        dp[i][j] = val

        return dp[n][k]

from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        # dp[a][b] = min cost to paint first i+1 houses from left and last i+1 from right
        # with left house colored a and right house colored b (a != b)
        dp = [[INF] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        half = n // 2
        for i in range(1, half):
            new_dp = [[INF] * 3 for _ in range(3)]
            for a2 in range(3):
                for b2 in range(3):
                    if a2 == b2:
                        continue
                    best = INF
                    for a in range(3):
                        if a == a2:
                            continue
                        for b in range(3):
                            if b == b2 or a == b:
                                continue
                            if dp[a][b] < best:
                                best = dp[a][b]
                    if best < INF:
                        new_dp[a2][b2] = best + cost[i][a2] + cost[n - 1 - i][b2]
            dp = new_dp

        ans = INF
        for a in range(3):
            for b in range(3):
                if a != b and dp[a][b] < ans:
                    ans = dp[a][b]
        return ans

from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Diagonals identified by (i - j). 
        # i - j >= 0: bottom-left triangle (including main diagonal) -> non-increasing
        # i - j < 0: top-right triangle -> non-decreasing
        from collections import defaultdict
        diags = defaultdict(list)
        for i in range(n):
            for j in range(n):
                diags[i - j].append(grid[i][j])

        for k, vals in diags.items():
            if k >= 0:
                vals.sort(reverse=True)
            else:
                vals.sort()

        # Put back
        idx = defaultdict(int)
        for i in range(n):
            for j in range(n):
                k = i - j
                grid[i][j] = diags[k][idx[k]]
                idx[k] += 1

        return grid

