class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        best_gain = 0
        for v in range(1, 51):
            if v == k:
                continue
            cur = 0
            mx = 0
            for num in nums:
                if num == v:
                    c = 1
                elif num == k:
                    c = -1
                else:
                    c = 0
                cur = c if cur + c < c else cur + c
                if cur > mx:
                    mx = cur
            if mx > best_gain:
                best_gain = mx
        return total_k + best_gain

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = s_cnt = e = w = 0
        ans = 0
        for i, c in enumerate(s):
            if c == 'N':
                n += 1
            elif c == 'S':
                s_cnt += 1
            elif c == 'E':
                e += 1
            else:
                w += 1
            L = i + 1
            d = abs(n - s_cnt) + abs(e - w) + 2 * k
            ans = max(ans, min(L, d))
        return ans

