class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Map each distinct element value to its smallest index in `elements`
        best = {}
        for j, e in enumerate(elements):
            if e not in best:
                best[e] = j

        result = []
        for g in groups:
            min_idx = -1
            i = 1
            while i * i <= g:
                if g % i == 0:
                    if i in best:
                        idx = best[i]
                        if min_idx == -1 or idx < min_idx:
                            min_idx = idx
                    pair = g // i
                    if pair != i and pair in best:
                        idx = best[pair]
                        if min_idx == -1 or idx < min_idx:
                            min_idx = idx
                i += 1
            result.append(min_idx)
        return result

class Solution:
    def separateSquares(self, squares):
        total = sum(l * l for _, _, l in squares)
        target = total / 2.0

        lo = min(y for _, y, _ in squares)
        hi = max(y + l for _, y, l in squares)

        def area_below(y):
            s = 0
            for _, yi, l in squares:
                if y <= yi:
                    continue
                elif y >= yi + l:
                    s += l * l
                else:
                    s += l * (y - yi)
            return s

        # Binary search for the y such that area_below(y) == target.
        # area_below is a continuous, non-decreasing piecewise-linear function of y.
        for _ in range(100):
            mid = (lo + hi) / 2.0
            if area_below(mid) < target:
                lo = mid
            else:
                hi = mid

        return lo

