from typing import List

class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []
        for i, row in enumerate(grid):
            if limits[i] <= 0:
                continue
            top = heapq.nlargest(limits[i], row)
            candidates.extend(top)
        if k <= 0:
            return 0
        return sum(heapq.nlargest(k, candidates))

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        first = {}
        last = {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i

        intervals = []
        for c in first:
            l = first[c]
            r = last[c]
            i = l
            valid = True
            while i <= r:
                ch = s[i]
                if first[ch] < l:
                    valid = False
                    break
                if last[ch] > r:
                    r = last[ch]
                i += 1
            if valid and not (l == 0 and r == n - 1):
                intervals.append((l, r))

        # Greedy: sort by right endpoint, pick non-overlapping intervals
        intervals.sort(key=lambda x: (x[1], x[0]))
        count = 0
        last_end = -1
        for l, r in intervals:
            if l > last_end:
                count += 1
                last_end = r

        return count >= k

from functools import lru_cache
from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        @lru_cache(maxsize=None)
        def solve(i: int, leftover: int) -> int:
            # leftover == -1 means no carried-over element
            remaining = n - i

            if leftover == -1:
                if remaining == 0:
                    return 0
                if remaining < 3:
                    # fewer than three elements remain; remove all in one op
                    return max(nums[i:i + remaining])
                a, b, c = nums[i], nums[i + 1], nums[i + 2]
                return min(
                    max(b, c) + solve(i + 3, a),
                    max(a, c) + solve(i + 3, b),
                    max(a, b) + solve(i + 3, c),
                )
            else:
                total = 1 + remaining  # effective array length including leftover
                if total < 3:
                    if remaining == 0:
                        return leftover
                    return max(leftover, nums[i])
                a, b, c = leftover, nums[i], nums[i + 1]
                return min(
                    max(b, c) + solve(i + 2, a),
                    max(a, c) + solve(i + 2, b),
                    max(a, b) + solve(i + 2, c),
                )

        ans = solve(0, -1)
        solve.cache_clear()
        return ans

class Solution:
    def countArrays(self, original, bounds):
        lo = -10**18
        hi = 10**18
        base = original[0]
        for i, (u, v) in enumerate(bounds):
            d = original[i] - base
            lo = max(lo, u - d)
            hi = min(hi, v - d)
        return max(0, hi - lo + 1)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        from functools import lru_cache

        def cost(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        @lru_cache(maxsize=None)
        def dp(i, j, budget):
            if i > j:
                return 0
            if i == j:
                return 1
            best = max(dp(i + 1, j, budget), dp(i, j - 1, budget))
            c = cost(s[i], s[j])
            if c <= budget:
                best = max(best, 2 + dp(i + 1, j - 1, budget - c))
            return best

        result = dp(0, n - 1, k)
        dp.cache_clear()
        return result

from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        if n == 0:
            return 0

        # Segment tree storing max capacity in range
        size = 1
        while size < n:
            size <<= 1
        tree = [-1] * (2 * size)

        # Build
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def find_and_remove(node, node_l, node_r, val):
            # Find leftmost position in [node_l, node_r] with capacity >= val
            if tree[node] < val:
                return -1
            if node_l == node_r:
                tree[node] = -1
                return node_l
            mid = (node_l + node_r) // 2
            if tree[2 * node] >= val:
                res = find_and_remove(2 * node, node_l, mid, val)
            else:
                res = find_and_remove(2 * node + 1, mid + 1, node_r, val)
            tree[node] = max(tree[2 * node], tree[2 * node + 1])
            return res

        unplaced = 0
        for q in fruits:
            if find_and_remove(1, 0, size - 1, q) == -1:
                unplaced += 1
        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def is_pal(x: str) -> bool:
            return x == x[::-1]

        n, m = len(s), len(t)

        s_subs = [""]
        for i in range(n):
            for j in range(i + 1, n + 1):
                s_subs.append(s[i:j])

        t_subs = [""]
        for i in range(m):
            for j in range(i + 1, m + 1):
                t_subs.append(t[i:j])

        best = 0
        for a in s_subs:
            for b in t_subs:
                c = a + b
                if c and is_pal(c):
                    if len(c) > best:
                        best = len(c)
        return best

class Solution:
    def minZeroArray(self, nums, queries):
        n = len(nums)
        # For each position, maintain a bitset of achievable subset sums
        # from the vals of queries that cover this position.
        achievable = [1] * n  # bit 0 set => sum 0 is achievable

        # Check if already a zero array
        if all(x == 0 for x in nums):
            return 0

        def all_done():
            for i in range(n):
                if not ((achievable[i] >> nums[i]) & 1):
                    return False
            return True

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                achievable[i] |= achievable[i] << val
            if all_done():
                return k

        return -1

from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(row) for row in properties]

        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[rx] = ry

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})

import sys

def main():
    input_data = sys.stdin.read().split()
    H = int(input_data[0])
    W = int(input_data[1])
    S = input_data[2:2+H]

    min_r, max_r = H, -1
    min_c, max_c = W, -1
    for i in range(H):
        row = S[i]
        for j in range(W):
            if row[j] == '#':
                if i < min_r: min_r = i
                if i > max_r: max_r = i
                if j < min_c: min_c = j
                if j > max_c: max_c = j

    if max_r == -1:
        print("Yes")
        return

    for i in range(H):
        row = S[i]
        for j in range(W):
            ch = row[j]
            inside = (min_r <= i <= max_r) and (min_c <= j <= max_c)
            if inside:
                if ch == '.':
                    print("No")
                    return
            else:
                if ch == '#':
                    print("No")
                    return
    print("Yes")

main()

import sys
from collections import defaultdict

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1

    cols = [[] for _ in range(W + 1)]  # 1-indexed
    for i in range(N):
        x = int(data[idx]); idx += 1
        y = int(data[idx]); idx += 1
        cols[x].append((y, i))

    rank = [0] * N
    min_c = None
    for x in range(1, W + 1):
        cols[x].sort()
        cx = len(cols[x])
        if min_c is None or cx < min_c:
            min_c = cx
        for r, (y, bi) in enumerate(cols[x], start=1):
            rank[bi] = r

    if min_c is None:
        min_c = 0

    # R[k] = max over columns of k-th smallest Y, for k = 1..min_c
    R = [0] * (min_c + 1)
    for x in range(1, W + 1):
        if not cols[x]:
            continue
        for k in range(1, min_c + 1):
            y_k = cols[x][k-1][0]
            if y_k > R[k]:
                R[k] = y_k

    Q = int(data[idx]); idx += 1
    out = []
    for _ in range(Q):
        T = int(data[idx]); idx += 1
        A = int(data[idx]) - 1; idx += 1
        j = rank[A]
        if j > min_c:
            out.append("Yes")
        else:
            if T < R[j]:
                out.append("Yes")
            else:
                out.append("No")

    sys.stdout.write('\n'.join(out) + '\n')

main()

