import sys

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    A = list(map(int, data[1:N+1]))

    # x_i in {0=none, 1=ARC, 2=CRA}
    # State (a,b) = (x_{i-1}, x_i), encoded as 3*a+b
    # Valid state: not (a!=0 and b!=0)
    # Transition (a,b)->(b,c) requires:
    #   dist1: not (b!=0 and c!=0)
    #   dist2: not (a!=0 and c!=0 and a==c)
    #   coverage of A at current position

    trans_mask = [[0]*9 for _ in range(2)]
    for Ai in range(2):
        for a in range(3):
            for b in range(3):
                if a != 0 and b != 0:
                    continue
                ab = 3*a + b
                for c in range(3):
                    if b != 0 and c != 0:
                        continue
                    if a != 0 and c != 0 and a == c:
                        continue
                    if Ai == 0 and b == 0 and c == 0:
                        continue
                    bc = 3*b + c
                    trans_mask[Ai][ab] |= 1 << bc

    table = [[0]*512 for _ in range(2)]
    for Ai in range(2):
        for mask in range(512):
            nm = 0
            for ab in range(9):
                if mask & (1 << ab):
                    nm |= trans_mask[Ai][ab]
            table[Ai][mask] = nm

    t0 = table[0]
    t1 = table[1]

    for x1 in range(3):
        for x2 in range(3):
            if x1 != 0 and x2 != 0:
                continue
            if A[1] == 0 and x1 == 0 and x2 == 0:
                continue

            mask = 1 << (3*x1 + x2)

            for i in range(2, N):
                if A[i] == 0:
                    mask = t0[mask]
                else:
                    mask = t1[mask]
                if mask == 0:
                    break

            if mask == 0:
                continue

            for ab in range(9):
                if not (mask & (1 << ab)):
                    continue
                a = ab // 3
                b = ab % 3
                # (a,b) = (x_{N-1}, x_N)
                if b != 0 and x1 != 0:
                    continue
                if a != 0 and x1 != 0 and a == x1:
                    continue
                if b != 0 and x2 != 0 and b == x2:
                    continue
                if A[0] == 0 and b == 0 and x1 == 0:
                    continue
                print("Yes")
                return

    print("No")

solve()

class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            mirror_idx = 25 - idx

            if stacks[mirror_idx]:
                j = stacks[mirror_idx].pop()
                score += i - j
            else:
                stacks[idx].append(i)

        return score

