class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        max_val = 300
        max_diff = 299

        # best[v][d] = max length of a valid subsequence ending with value v
        # whose last difference is at least d.
        best = [[0] * (max_diff + 1) for _ in range(max_val + 1)]

        ans = 1

        for x in nums:
            updates = []

            for y in range(1, max_val + 1):
                d = abs(x - y)
                if best[y][d]:
                    updates.append((d, best[y][d] + 1))

            # A single element subsequence ending at x can be extended by any next diff.
            updates.append((max_diff, 1))

            row = best[x]
            for d, length in updates:
                if length > row[d]:
                    row[d] = length
                    if length > ans:
                        ans = length

            # Rebuild suffix maxima for this value.
            for d in range(max_diff - 1, -1, -1):
                if row[d + 1] > row[d]:
                    row[d] = row[d + 1]

        return ans

