class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        events = []
        total_area = 0

        for _, y, l in squares:
            total_area += l * l
            events.append((y, l))
            events.append((y + l, -l))

        events.sort()
        target = total_area / 2.0

        current_area = 0.0
        slope = 0
        prev_y = events[0][0]
        i = 0
        n = len(events)

        while i < n:
            y = events[i][0]

            if y > prev_y:
                interval_area = slope * (y - prev_y)

                if slope == 0:
                    if current_area == target:
                        return float(prev_y)
                elif current_area + interval_area >= target:
                    return prev_y + (target - current_area) / slope

                current_area += interval_area
                prev_y = y

            while i < n and events[i][0] == y:
                slope += events[i][1]
                i += 1

        return float(prev_y)

