class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        if n <= 2:
            return max(nums)

        # dp[s] = minimum cost after processing elements before i,
        # where nums[s] is the only carried element at the front.
        dp = {
            2: max(nums[0], nums[1]),  # remove 0, 1
            1: max(nums[0], nums[2]),  # remove 0, 2
            0: max(nums[1], nums[2]),  # remove 1, 2
        }

        i = 3
        while i + 1 < n:
            ndp = {}

            for s, cost in dp.items():
                # First three available are: nums[s], nums[i], nums[i + 1]

                # Remove carried element and nums[i], carry nums[i + 1]
                new_cost = cost + max(nums[s], nums[i])
                ndp[i + 1] = min(ndp.get(i + 1, float("inf")), new_cost)

                # Remove carried element and nums[i + 1], carry nums[i]
                new_cost = cost + max(nums[s], nums[i + 1])
                ndp[i] = min(ndp.get(i, float("inf")), new_cost)

                # Remove nums[i] and nums[i + 1], keep carried element
                new_cost = cost + max(nums[i], nums[i + 1])
                ndp[s] = min(ndp.get(s, float("inf")), new_cost)

            dp = ndp
            i += 2

        ans = float("inf")
        for s, cost in dp.items():
            if i == n:
                ans = min(ans, cost + nums[s])
            else:
                ans = min(ans, cost + max(nums[s], nums[i]))

        return ans

