class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def cost(a: str, b: str) -> int:
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        for i in range(n):
            for budget in range(k + 1):
                dp[i][i][budget] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                pair_cost = cost(s[i], s[j])

                left = dp[i + 1][j]
                right = dp[i][j - 1]
                mid = dp[i + 1][j - 1] if i + 1 <= j - 1 else None
                cur = dp[i][j]

                for budget in range(k + 1):
                    best = max(left[budget], right[budget])

                    if budget >= pair_cost:
                        inside = mid[budget - pair_cost] if mid is not None else 0
                        best = max(best, inside + 2)

                    cur[budget] = best

        return dp[0][n - 1][k]

