class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        done = [x == 0 for x in nums]
        remaining = sum(not x for x in done)
        if remaining == 0:
            return 0

        dp = [1] * n  # bit s is set if sum s is achievable for that index
        masks = [(1 << (x + 1)) - 1 for x in nums]

        for k, (l, r, val) in enumerate(queries, start=1):
            for i in range(l, r + 1):
                if done[i]:
                    continue

                dp[i] = (dp[i] | (dp[i] << val)) & masks[i]

                if (dp[i] >> nums[i]) & 1:
                    done[i] = True
                    remaining -= 1

            if remaining == 0:
                return k

        return -1

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        t = '1' + s + '1'
        n = len(t)

        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0

        for idx in range(1, len(runs) - 1):
            ch, length = runs[idx]
            if ch == '1' and runs[idx - 1][0] == '0' and runs[idx + 1][0] == '0':
                best_gain = max(best_gain, runs[idx - 1][1] + runs[idx + 1][1])

        return base + best_gain

