class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(row) for row in properties]

        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})

import sys

def count_snake(n: int) -> int:
    if n < 10:
        return 0

    s = str(n)
    m = len(s)
    ans = 0

    for length in range(2, m):
        for first in range(1, 10):
            ans += first ** (length - 1)

    first_digit = int(s[0])

    for first in range(1, first_digit):
        ans += first ** (m - 1)

    top = first_digit
    for i in range(1, m):
        limit = int(s[i])
        remaining = m - i - 1

        choices_less_than_limit = min(top, limit)
        ans += choices_less_than_limit * (top ** remaining)

        if limit >= top:
            return ans

    ans += 1
    return ans


