def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    idx = 1
    out = []

    for _ in range(t):
        n = data[idx]
        idx += 1
        a = data[idx:idx + 2 * n]
        idx += 2 * n

        adjacent_same = [False] * (n + 1)
        first_edge = {}
        candidate = set()

        for i in range(2 * n - 1):
            x, y = a[i], a[i + 1]

            if x == y:
                adjacent_same[x] = True
                continue

            if x > y:
                x, y = y, x
            key = (x, y)

            if key in first_edge:
                if i - first_edge[key] > 1:
                    candidate.add(key)
            else:
                first_edge[key] = i

        ans = 0
        for x, y in candidate:
            if not adjacent_same[x] and not adjacent_same[y]:
                ans += 1

        out.append(str(ans))

    print("\n".join(out))

if __name__ == "__main__":
    solve()

import sys
from collections import deque

def main():
    input = sys.stdin.buffer.readline

    H, W = map(int, input().split())
    S = [input().strip() for _ in range(H)]
    A, B, C, D = map(int, input().split())

    start = (A - 1) * W + (B - 1)
    goal = (C - 1) * W + (D - 1)
    n = H * W

    INF = 10 ** 9
    dist = [INF] * n
    fixed = bytearray(n)
    dist[start] = 0

    dq = deque([start])
    DOT = ord(".")

    while dq:
        v = dq.popleft()
        if fixed[v]:
            continue
        fixed[v] = 1

        if v == goal:
            print(dist[v])
            return

        r = v // W
        c = v - r * W
        d = dist[v]

        # Move for free to adjacent original road cells.
        if r > 0:
            nv = v - W
            if S[r - 1][c] == DOT and d < dist[nv]:
                dist[nv] = d
                dq.appendleft(nv)
        if r + 1 < H:
            nv = v + W
            if S[r + 1][c] == DOT and d < dist[nv]:
                dist[nv] = d
                dq.appendleft(nv)
        if c > 0:
            nv = v - 1
            if S[r][c - 1] == DOT and d < dist[nv]:
                dist[nv] = d
                dq.appendleft(nv)
        if c + 1 < W:
            nv = v + 1
            if S[r][c + 1] == DOT and d < dist[nv]:
                dist[nv] = d
                dq.appendleft(nv)

        # One kick can make cells 1 or 2 steps away in one direction reachable.
        nd = d + 1

        if r > 0:
            nv = v - W
            if nd < dist[nv]:
                dist[nv] = nd
                dq.append(nv)
            if r > 1:
                nv = v - 2 * W
                if nd < dist[nv]:
                    dist[nv] = nd
                    dq.append(nv)

        if r + 1 < H:
            nv = v + W
            if nd < dist[nv]:
                dist[nv] = nd
                dq.append(nv)
            if r + 2 < H:
                nv = v + 2 * W
                if nd < dist[nv]:
                    dist[nv] = nd
                    dq.append(nv)

        if c > 0:
            nv = v - 1
            if nd < dist[nv]:
                dist[nv] = nd
                dq.append(nv)
            if c > 1:
                nv = v - 2
                if nd < dist[nv]:
                    dist[nv] = nd
                    dq.append(nv)

        if c + 1 < W:
            nv = v + 1
            if nd < dist[nv]:
                dist[nv] = nd
                dq.append(nv)
            if c + 2 < W:
                nv = v + 2
                if nd < dist[nv]:
                    dist[nv] = nd
                    dq.append(nv)

    print(dist[goal])

if __name__ == "__main__":
    main()

