    main()

class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0

        for i, c in enumerate(s):
            idx = ord(c) - ord('a')
            mirror_idx = 25 - idx

            if stacks[mirror_idx]:
                j = stacks[mirror_idx].pop()
                score += i - j
            else:
                stacks[idx].append(i)

        return score

