class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG = -10**18

        dp = [[[NEG] * 3 for _ in range(n)] for _ in range(m)]

        start = coins[0][0]
        dp[0][0][0] = start
        if start < 0:
            dp[0][0][1] = 0
            dp[0][0][2] = 0
        else:
            dp[0][0][1] = start
            dp[0][0][2] = start

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                value = coins[i][j]

                for k in range(3):
                    best = NEG

                    if i > 0:
                        best = max(best, dp[i - 1][j][k] + value)
                    if j > 0:
                        best = max(best, dp[i][j - 1][k] + value)

                    if value < 0 and k > 0:
                        if i > 0:
                            best = max(best, dp[i - 1][j][k - 1])
                        if j > 0:
                            best = max(best, dp[i][j - 1][k - 1])

                    dp[i][j][k] = best

        return max(dp[m - 1][n - 1])

from typing import List

class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (n + 1)
        inv_fact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n - 1, -1, -1):
            inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        ans = 0
        for i, x in enumerate(nums):
            count = 0
            for j in range(k):
                count = (count + comb(i, j)) % MOD

            ans = (ans + x * count) % MOD
            ans = (ans + nums[n - 1 - i] * count) % MOD

        return ans

