class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()
        n = len(coins)

        prefix = [0] * (n + 1)
        for i, (l, r, c) in enumerate(coins):
            prefix[i + 1] = prefix[i] + (r - l + 1) * c

        ans = 0

        j = 0
        for i in range(n):
            start = coins[i][0]
            end = start + k - 1

            if j < i:
                j = i

            while j < n and coins[j][1] <= end:
                j += 1

            total = prefix[j] - prefix[i]

            if j < n and coins[j][0] <= end:
                total += (end - coins[j][0] + 1) * coins[j][2]

            ans = max(ans, total)

        j = n - 1
        for i in range(n - 1, -1, -1):
            end = coins[i][1]
            start = end - k + 1

            if j > i:
                j = i

            while j >= 0 and coins[j][0] >= start:
                j -= 1

            total = prefix[i + 1] - prefix[j + 1]

            if j >= 0 and coins[j][1] >= start:
                total += (coins[j][1] - start + 1) * coins[j][2]

            ans = max(ans, total)

        return ans

