class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        V = 301
        D = 300

        seen = [False] * V
        dp = [[0] * (D + 1) for _ in range(V)]

        ans = 1

        for x in nums:
            exact = [0] * (D + 1)

            for v in range(1, V):
                if seen[v]:
                    diff = abs(x - v)
                    exact[diff] = max(exact[diff], dp[v][diff] + 1)

            if not seen[x]:
                seen[x] = True
                for d in range(D + 1):
                    dp[x][d] = 1

            best = 0
            row = dp[x]
            for d in range(D, -1, -1):
                best = max(best, exact[d])
                row[d] = max(row[d], best)

            ans = max(ans, row[0])

        return ans

