class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)

        for i, num in enumerate(nums):
            prefix[i + 1] = prefix[i] + num

        NEG_INF = float("-inf")

        dp = [[NEG_INF] * (n + 1) for _ in range(k + 1)]

        for i in range(n + 1):
            dp[0][i] = 0

        for j in range(1, k + 1):
            best = NEG_INF

            for i in range(j * m, n + 1):
                start = i - m

                if dp[j - 1][start] != NEG_INF:
                    best = max(best, dp[j - 1][start] - prefix[start])

                dp[j][i] = max(dp[j][i - 1], best + prefix[i])

        return dp[k][n]

