class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**18
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]

        dp = {
            (a, b): cost[0][a] + cost[n - 1][b]
            for a, b in pairs
        }

        for i in range(1, n // 2):
            new_dp = {}
            for a, b in pairs:
                best = INF
                for (pa, pb), val in dp.items():
                    if pa != a and pb != b:
                        best = min(best, val)
                new_dp[(a, b)] = best + cost[i][a] + cost[n - 1 - i][b]
            dp = new_dp

        return min(dp.values())

