class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        best_gain = 0

        for v in range(1, 51):
            if v == k:
                continue

            cur = 0
            for num in nums:
                if num == v:
                    cur += 1
                elif num == k:
                    cur -= 1

                cur = max(cur, 0)
                best_gain = max(best_gain, cur)

        return total_k + best_gain

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n_cnt = s_cnt = e_cnt = w_cnt = 0
        ans = 0

        for i, ch in enumerate(s, 1):
            if ch == 'N':
                n_cnt += 1
            elif ch == 'S':
                s_cnt += 1
            elif ch == 'E':
                e_cnt += 1
            else:
                w_cnt += 1

            base = abs(n_cnt - s_cnt) + abs(e_cnt - w_cnt)
            ans = max(ans, min(i, base + 2 * k))

        return ans

