class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        assigned_by_value = [-1] * (max_group + 1)
        seen = set()

        for idx, value in enumerate(elements):
            if value in seen:
                continue
            seen.add(value)

            if value > max_group:
                continue

            for multiple in range(value, max_group + 1, value):
                if assigned_by_value[multiple] == -1:
                    assigned_by_value[multiple] = idx

        return [assigned_by_value[group] for group in groups]

