class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        total = sum(l * l for _, _, l in squares)
        target = total / 2

        events = []
        for _, y, l in squares:
            events.append((y, l))
            events.append((y + l, -l))

        events.sort()

        area = 0.0
        active_width = 0
        prev_y = events[0][0]
        i = 0

        while i < len(events):
            y = events[i][0]
            height = y - prev_y

            if active_width and area + active_width * height >= target:
                return prev_y + (target - area) / active_width

            area += active_width * height

            while i < len(events) and events[i][0] == y:
                active_width += events[i][1]
                i += 1

            if area >= target:
                return float(y)

            prev_y = y

        return float(prev_y)

