class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        first = [n] * 26
        last = [-1] * 26

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            first[idx] = min(first[idx], i)
            last[idx] = i

        intervals = []

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            if first[idx] != i:
                continue

            end = last[idx]
            pos = i
            valid = True

            while pos <= end:
                cur = ord(s[pos]) - ord('a')
                if first[cur] < i:
                    valid = False
                    break
                end = max(end, last[cur])
                pos += 1

            if valid and not (i == 0 and end == n - 1):
                intervals.append((end, i))

        intervals.sort()

        count = 0
        prev_end = -1

        for end, start in intervals:
            if start > prev_end:
                count += 1
                prev_end = end
                if count >= k:
                    return True

        return False

