class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1

        tree = [0] * (2 * size)
        for i, capacity in enumerate(baskets):
            tree[size + i] = capacity

        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def place(fruit: int) -> bool:
            if tree[1] < fruit:
                return False

            node = 1
            while node < size:
                left = node * 2
                if tree[left] >= fruit:
                    node = left
                else:
                    node = left + 1

            tree[node] = 0
            node //= 2
            while node:
                tree[node] = max(tree[2 * node], tree[2 * node + 1])
                node //= 2

            return True

        unplaced = 0
        for fruit in fruits:
            if not place(fruit):
                unplaced += 1

        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        ns, nt = len(s), len(t)

        best_s = [0] * (ns + 1)
        for i in range(ns):
            for j in range(i, ns):
                sub = s[i:j + 1]
                if sub == sub[::-1]:
                    best_s[i] = max(best_s[i], j - i + 1)

        best_t_end = [0] * nt
        for j in range(nt):
            for i in range(j + 1):
                sub = t[i:j + 1]
                if sub == sub[::-1]:
                    best_t_end[j] = max(best_t_end[j], j - i + 1)

        ans = max(max(best_s), max(best_t_end))

        for i in range(ns):
            for j in range(nt):
                matched = 0
                while (
                    i + matched < ns
                    and j - matched >= 0
                    and s[i + matched] == t[j - matched]
                ):
                    matched += 1

                for k in range(1, matched + 1):
                    ans = max(ans, 2 * k)

                    if i + k < ns:
                        ans = max(ans, 2 * k + best_s[i + k])

                    if j - k >= 0:
                        ans = max(ans, 2 * k + best_t_end[j - k])

        return ans

from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        m = len(queries)

        if all(x == 0 for x in nums):
            return 0

        def can_make_zero(k: int) -> bool:
            for i, target in enumerate(nums):
                if target == 0:
                    continue

                reachable = 1
                mask = (1 << (target + 1)) - 1

                for l, r, val in queries[:k]:
                    if l <= i <= r:
                        reachable |= reachable << val
                        reachable &= mask

                if not (reachable >> target) & 1:
                    return False

            return True

        left, right = 1, m
        answer = -1

        while left <= right:
            mid = (left + right) // 2
            if can_make_zero(mid):
                answer = mid
                right = mid - 1
            else:
                left = mid + 1

        return answer

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        zero_runs = []
        n = len(s)
        i = 0

        while i < n:
            if s[i] == '0':
                j = i
                while j < n and s[j] == '0':
                    j += 1
                zero_runs.append(j - i)
                i = j
            else:
                i += 1

        if len(zero_runs) < 2:
            return ones

        best_gain = 0
        for i in range(len(zero_runs) - 1):
            best_gain = max(best_gain, zero_runs[i] + zero_runs[i + 1])

        return ones + best_gain

from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(p) for p in properties]

        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_x] = root_y

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})

import sys

def count_snake_le(n):
    if n < 10:
        return 0

    s = str(n)
    length = len(s)
    total = 0

    for d in range(2, length):
        for top in range(1, 10):
            total += top ** (d - 1)

    first = int(s[0])

    for top in range(1, first):
        total += top ** (length - 1)

    top = first
    for i in range(1, length):
        digit = int(s[i])
        max_allowed = top - 1

        choices_less = min(digit - 1, max_allowed) + 1
        if choices_less > 0:
            total += choices_less * (top ** (length - 1 - i))

        if digit > max_allowed:
            break
    else:
        total += 1

    return total

def main():
    l, r = map(int, sys.stdin.read().split())
    print(count_snake_le(r) - count_snake_le(l - 1))

if __name__ == "__main__":
    main()

import sys

def solve():
    data = sys.stdin.read().split()
    H = int(data[0])
    W = int(data[1])
    grid = data[2:2 + H]

    min_r, max_r = H, -1
    min_c, max_c = W, -1

    for i in range(H):
        for j, ch in enumerate(grid[i]):
            if ch == '#':
                min_r = min(min_r, i)
                max_r = max(max_r, i)
                min_c = min(min_c, j)
                max_c = max(max_c, j)

    for i in range(min_r, max_r + 1):
        for j in range(min_c, max_c + 1):
            if grid[i][j] == '.':
                print("No")
                return

    print("Yes")

if __name__ == "__main__":
    solve()

import sys

def main():
    S = sys.stdin.readline().strip()
    out = []
    w_count = 0

    for ch in S:
        if ch == 'W':
            w_count += 1
        elif ch == 'A':
            out.append('A')
            if w_count:
                out.append('C' * w_count)
                w_count = 0
        else:
            if w_count:
                out.append('W' * w_count)
                w_count = 0
            out.append(ch)

    if w_count:
        out.append('W' * w_count)

    print(''.join(out))

