def main():
    S = sys.stdin.readline().strip()

    pairs = {')': '(', ']': '[', '>': '<'}
    opens = set("([<")
    stack = []

    for c in S:
        if c in opens:
            stack.append(c)
        else:
            if not stack or stack[-1] != pairs[c]:
                print("No")
                return
            stack.pop()

    print("Yes" if not stack else "No")

