import sys

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1

    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    ans = 0
    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        if not union(u, v):
            ans += 1

    print(ans)

if __name__ == "__main__":
    main()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    T = data[idx]
    idx += 1
    ans = []

    for _ in range(T):
        N = data[idx]
        idx += 1
        A = data[idx:idx + 2 * N]
        idx += 2 * N

        first = [-1] * (N + 1)
        second = [-1] * (N + 1)

        for i, x in enumerate(A):
            if first[x] == -1:
                first[x] = i
            else:
                second[x] = i

        non_adjacent = [False] * (N + 1)
        for x in range(1, N + 1):
            non_adjacent[x] = second[x] - first[x] > 1

        seen = {}

        for i in range(2 * N - 1):
            x, y = A[i], A[i + 1]
            if x == y:
                continue
            if x > y:
                x, y = y, x

            key = (x, y)
            if key not in seen:
                seen[key] = [i, i]
            else:
                seen[key][1] = i

        count = 0
        for (x, y), (l, r) in seen.items():
            if non_adjacent[x] and non_adjacent[y] and r - l >= 2:
                count += 1

        ans.append(str(count))

    sys.stdout.write("\n".join(ans))

if __name__ == "__main__":
    solve()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    S = bytearray(data[2])
    T = data[3]

    cnt = [0] * 10
    for b in T:
        cnt[b - 48] += 1

    last_digit = T[-1] - 48
    replaced = bytearray(N)
    top = 9
    used_last_digit = False

    for i in range(N):
        while top > 0 and cnt[top] == 0:
            top -= 1
        if top == 0:
            break

        cur = S[i] - 48
        if top > cur:
            S[i] = top + 48
            cnt[top] -= 1
            replaced[i] = 1
            if top == last_digit:
                used_last_digit = True

    if not used_last_digit:
        last_byte = last_digit + 48
        for i in range(N - 1, -1, -1):
            if not replaced[i] and S[i] - 48 <= last_digit:
                S[i] = last_byte
                break
        else:
            S[N - 1] = last_byte

    sys.stdout.buffer.write(bytes(S) + b"\n")

if __name__ == "__main__":
    solve()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    A = list(map(int, data[1:1 + N]))

    trans = [[0] * 9 for _ in range(2)]

    for x in range(3):
        for y in range(3):
            old = 3 * x + y
            for z in range(3):
                if y != 0 and z != 0:
                    continue
                if x != 0 and z != 0 and x == z:
                    continue

                new = 3 * y + z
                for av in range(2):
                    if av == 0 and y == 0 and z == 0:
                        continue
                    trans[av][old] |= 1 << new

    trans_mask = [[0] * 512 for _ in range(2)]
    for av in range(2):
        for mask in range(512):
            nxt = 0
            m = mask
            while m:
                lb = m & -m
                s = lb.bit_length() - 1
                nxt |= trans[av][s]
                m ^= lb
            trans_mask[av][mask] = nxt

    for d0 in range(3):
        for d1 in range(3):
            if d0 != 0 and d1 != 0:
                continue
            if A[1] == 0 and d0 == 0 and d1 == 0:
                continue

            cur = 1 << (3 * d0 + d1)

            for i in range(2, N):
                cur = trans_mask[A[i]][cur]
                if cur == 0:
                    break

            if cur == 0:
                continue

            m = cur
            while m:
                lb = m & -m
                s = lb.bit_length() - 1
                m ^= lb

                dn2 = s // 3
                dn1 = s % 3

                if dn1 != 0 and d0 != 0:
                    continue
                if dn2 != 0 and d0 != 0 and dn2 == d0:
                    continue
                if dn1 != 0 and d1 != 0 and dn1 == d1:
                    continue
                if A[0] == 0 and d0 == 0 and dn1 == 0:
                    continue

                print("Yes")
                return

    print("No")

