    solve()

class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0

        for i, ch in enumerate(s):
            c = ord(ch) - ord('a')
            mirror = 25 - c

            if stacks[mirror]:
                j = stacks[mirror].pop()
                score += i - j
            else:
                stacks[c].append(i)

        return score

from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = -10**18

        dp = [[NEG_INF] * 3 for _ in range(n)]

        for i in range(m):
            new_dp = [[NEG_INF] * 3 for _ in range(n)]

            for j in range(n):
                val = coins[i][j]

                if i == 0 and j == 0:
                    new_dp[j][0] = val
                    if val < 0:
                        new_dp[j][1] = 0
                    continue

                for used in range(3):
                    best_prev = NEG_INF

                    if i > 0:
                        best_prev = max(best_prev, dp[j][used])
                    if j > 0:
                        best_prev = max(best_prev, new_dp[j - 1][used])

                    if best_prev == NEG_INF:
                        continue

                    new_dp[j][used] = max(new_dp[j][used], best_prev + val)

                    if val < 0 and used < 2:
                        new_dp[j][used + 1] = max(new_dp[j][used + 1], best_prev)

            dp = new_dp

        return max(dp[n - 1])

from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        MAX_VAL = 300
        INF_DIFF = 300

        dp = [[0] * (INF_DIFF + 1) for _ in range(MAX_VAL + 1)]
        suf = [[0] * (INF_DIFF + 2) for _ in range(MAX_VAL + 1)]

        ans = 1

        for x in nums:
            updates = []

            for prev in range(1, MAX_VAL + 1):
                diff = abs(x - prev)
                best_prev = suf[prev][diff]
                if best_prev:
                    updates.append((diff, best_prev + 1))

            updates.append((INF_DIFF, 1))

            changed = False
            for diff, length in updates:
                if length > dp[x][diff]:
                    dp[x][diff] = length
                    ans = max(ans, length)
                    changed = True

            if changed:
                running = 0
                for diff in range(INF_DIFF, -1, -1):
                    running = max(running, dp[x][diff])
                    suf[x][diff] = running

        return ans

