import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Since threshold >= 1, each non-zero node only needs to keep one
        # outgoing edge to reach 0, so threshold is effectively non-binding.
        # We need: every node can reach 0 using edges of weight <= W; minimize W.
        # Equivalently, in the reversed graph, find for each node the minimum
        # possible "bottleneck" (max edge weight) on a path from 0 to it.

        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in rev[u]:
                nd = d if d > w else w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

        ans = 0
        for i in range(n):
            if dist[i] == INF:
                return -1
            if dist[i] > ans:
                ans = dist[i]

        return ans if ans > 0 else -1 if n > 1 and any(True for _ in [0]) and False else ans

