class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        for event_type, timestamp_str, data in events:
            time = int(timestamp_str)

            if event_type == "OFFLINE":
                user_id = int(data)
                offline_until[user_id] = time + 60
            else:
                for token in data.split():
                    if token == "ALL":
                        for user_id in range(numberOfUsers):
                            mentions[user_id] += 1
                    elif token == "HERE":
                        for user_id in range(numberOfUsers):
                            if offline_until[user_id] <= time:
                                mentions[user_id] += 1
                    else:
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions

from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums, 1):
            prefix[i] = prefix[i - 1] + x

        neg_inf = -10**18
        prev = [0] * (n + 1)

        for _ in range(1, k + 1):
            curr = [neg_inf] * (n + 1)
            best = neg_inf

            for i in range(1, n + 1):
                curr[i] = curr[i - 1]

                if i >= m and prev[i - m] != neg_inf:
                    best = max(best, prev[i - m] - prefix[i - m])

                if best != neg_inf:
                    curr[i] = max(curr[i], prefix[i] + best)

            prev = curr

        return prev[n]

