class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        m = n // 2
        INF = 10**30

        dp = {}
        for a, b in pairs:
            dp[(a, b)] = cost[0][a] + cost[n - 1][b]

        for i in range(1, m):
            ndp = {}
            left = i
            right = n - 1 - i

            for a, b in pairs:
                best = INF
                add = cost[left][a] + cost[right][b]

                for pa, pb in pairs:
                    if a != pa and b != pb:
                        if dp[(pa, pb)] + add < best:
                            best = dp[(pa, pb)] + add

                ndp[(a, b)] = best

            dp = ndp

        return min(dp.values())

