from collections import defaultdict

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        positions = defaultdict(list)

        for i, x in enumerate(nums):
            positions[x].append(i)

        nearest = [-1] * n

        for inds in positions.values():
            m = len(inds)
            if m == 1:
                continue

            for k, idx in enumerate(inds):
                prev_idx = inds[k - 1]
                next_idx = inds[(k + 1) % m]

                d1 = abs(idx - prev_idx)
                d2 = abs(idx - next_idx)

                nearest[idx] = min(d1, n - d1, d2, n - d2)

        return [nearest[q] for q in queries]

