class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        ans = base

        for v in range(1, 51):
            if v == k:
                continue

            cur = 0
            best = 0

            for num in nums:
                if num == v:
                    delta = 1
                elif num == k:
                    delta = -1
                else:
                    delta = 0

                cur = max(0, cur + delta)
                best = max(best, cur)

            ans = max(ans, base + best)

        return ans

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        quadrants = [
            {'N', 'E'},
            {'N', 'W'},
            {'S', 'E'},
            {'S', 'W'},
        ]

        bad = [0, 0, 0, 0]
        ans = 0

        for i, ch in enumerate(s, 1):
            for q, good_dirs in enumerate(quadrants):
                if ch not in good_dirs:
                    bad[q] += 1

                distance = i - 2 * max(0, bad[q] - k)
                ans = max(ans, distance)

        return ans

