class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        INF = 10**9

        first_index = [INF] * (max_group + 1)
        for idx, value in enumerate(elements):
            if value <= max_group and first_index[value] == INF:
                first_index[value] = idx

        best_for_group_value = [INF] * (max_group + 1)

        for value in range(1, max_group + 1):
            idx = first_index[value]
            if idx == INF:
                continue
            for multiple in range(value, max_group + 1, value):
                if idx < best_for_group_value[multiple]:
                    best_for_group_value[multiple] = idx

        return [
            best_for_group_value[g] if best_for_group_value[g] != INF else -1
            for g in groups
        ]

