class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []

        for row, limit in zip(grid, limits):
            if limit > 0:
                top = sorted(row, reverse=True)[:limit]
                candidates.extend(top)

        candidates.sort(reverse=True)
        return sum(candidates[:k])

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        first = [n] * 26
        last = [-1] * 26

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            first[idx] = min(first[idx], i)
            last[idx] = i

        intervals = []

        for c in range(26):
            if last[c] == -1:
                continue

            l = first[c]
            r = last[c]
            i = l
            valid = True

            while i <= r:
                idx = ord(s[i]) - ord('a')
                if first[idx] < l:
                    valid = False
                    break
                if last[idx] > r:
                    r = last[idx]
                i += 1

            if valid and not (l == 0 and r == n - 1):
                intervals.append((l, r))

        intervals.sort(key=lambda x: x[1])

        count = 0
        prev_end = -1

        for l, r in intervals:
            if l > prev_end:
                count += 1
                prev_end = r
                if count >= k:
                    return True

        return False

from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 2:
            return max(nums)

        dp = {}
        for keep in range(3):
            removed = [i for i in range(3) if i != keep]
            dp[keep] = max(nums[removed[0]], nums[removed[1]])

        i = 3
        while i + 1 < n:
            ndp = {}
            a, b = i, i + 1

            for carry, cost in dp.items():
                options = [
                    (carry, max(nums[a], nums[b])),
                    (a, max(nums[carry], nums[b])),
                    (b, max(nums[carry], nums[a])),
                ]

                for new_carry, add in options:
                    new_cost = cost + add
                    if new_carry not in ndp or new_cost < ndp[new_carry]:
                        ndp[new_carry] = new_cost

            dp = ndp
            i += 2

        ans = float("inf")
        for carry, cost in dp.items():
            if i == n:
                ans = min(ans, cost + nums[carry])
            else:
                ans = min(ans, cost + max(nums[carry], nums[i]))

        return ans

