class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)

        size = 1
        while size < n:
            size <<= 1

        seg = [0] * (2 * size)

        for i, capacity in enumerate(baskets):
            seg[size + i] = capacity

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        unplaced = 0

        for fruit in fruits:
            if seg[1] < fruit:
                unplaced += 1
                continue

            idx = 1
            while idx < size:
                if seg[2 * idx] >= fruit:
                    idx = 2 * idx
                else:
                    idx = 2 * idx + 1

            seg[idx] = 0
            idx //= 2

            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx //= 2

        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def substrings(x: str):
            res = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    res.append(x[i:j])
            return res

        subs_s = substrings(s)
        subs_t = substrings(t)

        best = 0
        for a in subs_s:
            for b in subs_t:
                length = len(a) + len(b)
                if length <= best:
                    continue
                candidate = a + b
                if candidate == candidate[::-1]:
                    best = length

        return best

