class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)

        prefix = [0] * (n + 1)
        for i, s in enumerate(skill):
            prefix[i + 1] = prefix[i] + s

        start = 0

        for j in range(len(mana) - 1):
            cur = mana[j]
            nxt = mana[j + 1]

            delay = 0
            for i in range(n):
                needed = cur * prefix[i + 1] - nxt * prefix[i]
                if needed > delay:
                    delay = needed

            start += delay

        return start + mana[-1] * prefix[-1]

