class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n, m = len(nums), len(queries)

        def can(k: int) -> bool:
            for i, target in enumerate(nums):
                if target == 0:
                    continue
                bits = 1  # bit s means sum s is achievable
                mask = (1 << (target + 1)) - 1
                found = False
                for l, r, val in queries[:k]:
                    if l <= i <= r:
                        bits |= bits << val
                        bits &= mask
                        if (bits >> target) & 1:
                            found = True
                            break
                if not found:
                    return False
            return True

        if can(0):
            return 0
        if not can(m):
            return -1

        left, right = 1, m
        while left < right:
            mid = (left + right) // 2
            if can(mid):
                right = mid
            else:
                left = mid + 1

        return left

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        t = '1' + s + '1'
        n = len(t)

        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        for k in range(1, len(runs) - 1):
            ch, _ = runs[k]
            if ch == '1' and runs[k - 1][0] == '0' and runs[k + 1][0] == '0':
                best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])

        return base + best_gain

