class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(row) for row in properties]

        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})

import sys

def count_snake_upto(n: int) -> int:
    if n < 10:
        return 0

    s = str(n)
    length = len(s)
    ans = 0

    for m in range(2, length):
        for first in range(1, 10):
            ans += first ** (m - 1)

    top = int(s[0])
    rest = s[1:]
    m = length

    for first in range(1, top):
        ans += first ** (m - 1)

    first = top
    for i, ch in enumerate(rest):
        b = int(ch)
        rem = len(rest) - i - 1

        smaller_choices = min(b, first)
        ans += smaller_choices * (first ** rem)

        if b >= first:
            break
    else:
        ans += 1

    return ans

def main():
    l, r = map(int, sys.stdin.readline().split())
    print(count_snake_upto(r) - count_snake_upto(l - 1))

