def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    N = data[idx]
    idx += 1

    sizes = []
    dice = []

    for _ in range(N):
        k = data[idx]
        idx += 1
        counts = {}
        for a in data[idx:idx + k]:
            counts[a] = counts.get(a, 0) + 1
        idx += k
        sizes.append(k)
        dice.append(counts)

    ans = 0.0

    for i in range(N):
        for j in range(i + 1, N):
            if len(dice[i]) <= len(dice[j]):
                small, large = dice[i], dice[j]
            else:
                small, large = dice[j], dice[i]

            same = 0
            for value, cnt in small.items():
                large_cnt = large.get(value)
                if large_cnt:
                    same += cnt * large_cnt

            prob = same / (sizes[i] * sizes[j])
            if prob > ans:
                ans = prob

    print(f"{ans:.15f}")

