import sys

def solve():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        a = list(map(int, data[idx:idx + 2 * n]))
        idx += 2 * n

        bad = [False] * (n + 1)
        for i in range(2 * n - 1):
            if a[i] == a[i + 1]:
                bad[a[i]] = True

        first = {}
        ans = 0
        base = n + 1

        for i in range(2 * n - 1):
            x = a[i]
            y = a[i + 1]
            if x == y or bad[x] or bad[y]:
                continue

            if x > y:
                x, y = y, x
            key = x * base + y

            prev = first.get(key)
            if prev is None:
                first[key] = i
            elif prev >= 0 and i - prev >= 2:
                ans += 1
                first[key] = -1

        out.append(str(ans))

    sys.stdout.write("\n".join(out) + "\n")

