class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = {}
        score = 0
        for i, c in enumerate(s):
            mirror = chr(ord('a') + ord('z') - ord(c))
            if mirror in stacks and stacks[mirror]:
                j = stacks[mirror].pop()
                score += i - j
            else:
                if c not in stacks:
                    stacks[c] = []
                stacks[c].append(i)
        return score

from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = float('-inf')
        dp = [[[NEG_INF] * 3 for _ in range(n)] for _ in range(m)]

        dp[0][0][0] = coins[0][0]
        dp[0][0][1] = max(coins[0][0], 0)
        dp[0][0][2] = max(coins[0][0], 0)

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                for k in range(3):
                    best_prev_take = NEG_INF
                    if i > 0:
                        best_prev_take = max(best_prev_take, dp[i-1][j][k])
                    if j > 0:
                        best_prev_take = max(best_prev_take, dp[i][j-1][k])
                    take = best_prev_take + coins[i][j] if best_prev_take != NEG_INF else NEG_INF

                    neutralize = NEG_INF
                    if k >= 1:
                        if i > 0:
                            neutralize = max(neutralize, dp[i-1][j][k-1])
                        if j > 0:
                            neutralize = max(neutralize, dp[i][j-1][k-1])

                    dp[i][j][k] = max(take, neutralize)

                dp[i][j][1] = max(dp[i][j][1], dp[i][j][0])
                dp[i][j][2] = max(dp[i][j][2], dp[i][j][1])

        return dp[m-1][n-1][2]

class Solution:
    def maximumCoins(self, coins, k):
        coins.sort()
        n = len(coins)
        ans = 0

        # Case 1: window left-aligned at some segment's left endpoint
        j = 0
        full_sum = 0
        for i in range(n):
            if j < i:
                j = i
                full_sum = 0
            end = coins[i][0] + k - 1
            while j < n and coins[j][1] <= end:
                full_sum += (coins[j][1] - coins[j][0] + 1) * coins[j][2]
                j += 1
            total = full_sum
            if j < n and coins[j][0] <= end:
                total += (end - coins[j][0] + 1) * coins[j][2]
            if total > ans:
                ans = total
            if i < j:
                full_sum -= (coins[i][1] - coins[i][0] + 1) * coins[i][2]

        # Case 2: window right-aligned at some segment's right endpoint
        j = n - 1
        full_sum = 0
        for i in range(n - 1, -1, -1):
            if j > i:
                j = i
                full_sum = 0
            start = coins[i][1] - k + 1
            while j >= 0 and coins[j][0] >= start:
                full_sum += (coins[j][1] - coins[j][0] + 1) * coins[j][2]
                j -= 1
            total = full_sum
            if j >= 0 and coins[j][1] >= start:
                total += (coins[j][1] - start + 1) * coins[j][2]
            if total > ans:
                ans = total
            if i > j:
                full_sum -= (coins[i][1] - coins[i][0] + 1) * coins[i][2]

        return ans

from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        MAXV = 300
        D = 299  # max possible |diff|
        # best[v][d] = max length of subseq ending at some prior index with value v
        # such that either length == 1 or last difference >= d (suffix-max form)
        best = [[0] * (D + 2) for _ in range(MAXV + 2)]
        ans = 1
        for x in nums:
            new_dp = [0] * (D + 1)
            for d in range(D + 1):
                p1 = best[x - d][d] if (x - d) >= 1 else 0
                p2 = best[x + d][d] if (x + d) <= MAXV else 0
                pm = p1 if p1 > p2 else p2
                if pm > 0:
                    new_dp[d] = pm + 1
            # Update best[x] as suffix-max, combined with single-element baseline (1)
            cur_max = 0
            bx = best[x]
            for d in range(D, -1, -1):
                if new_dp[d] > cur_max:
                    cur_max = new_dp[d]
                v = cur_max if cur_max > 1 else 1
                if v > bx[d]:
                    bx[d] = v
            if cur_max > ans:
                ans = cur_max
        return ans

