from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        adj = defaultdict(list)
        for a, b, w in edges:
            adj[b].append((a, w))

        INF = float('inf')
        dist = [INF] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                nd = d if d > w else w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

        ans = 0
        for i in range(n):
            if dist[i] == INF:
                return -1
            if dist[i] > ans:
                ans = dist[i]
        return ans

class Solution:
    def countMentions(self, numberOfUsers, events):
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        # Sort by timestamp; at same timestamp, OFFLINE before MESSAGE
        sorted_events = sorted(
            events,
            key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1)
        )

        for typ, ts_str, payload in sorted_events:
            t = int(ts_str)
            if typ == "OFFLINE":
                offline_until[int(payload)] = t + 60
            else:  # MESSAGE
                if payload == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif payload == "HERE":
                    for i in range(numberOfUsers):
                        if offline_until[i] <= t:
                            mentions[i] += 1
                else:
                    for token in payload.split():
                        uid = int(token[2:])
                        mentions[uid] += 1

        return mentions

from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        S = [0] * (n + 1)
        for i in range(n):
            S[i + 1] = S[i] + nums[i]

        NEG = float('-inf')
        prev = [0] * (n + 1)  # j = 0: zero subarrays => sum 0 for any i

        for j in range(1, k + 1):
            curr = [NEG] * (n + 1)
            best = NEG  # max over valid p <= i - m of (prev[p] - S[p])
            for i in range(j * m, n + 1):
                p = i - m
                if prev[p] != NEG:
                    val = prev[p] - S[p]
                    if val > best:
                        best = val
                option1 = curr[i - 1]
                option2 = S[i] + best if best != NEG else NEG
                curr[i] = option1 if option1 > option2 else option2
            prev = curr

        return prev[n]

from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = float('inf')
        dp = [[INF] * 3 for _ in range(3)]
        for cl in range(3):
            for cr in range(3):
                if cl != cr:
                    dp[cl][cr] = cost[0][cl] + cost[n - 1][cr]

        half = n // 2
        for i in range(1, half):
            left_idx = i
            right_idx = n - 1 - i
            new_dp = [[INF] * 3 for _ in range(3)]
            for cl2 in range(3):
                for cr2 in range(3):
                    if cl2 == cr2:
                        continue
                    add = cost[left_idx][cl2] + cost[right_idx][cr2]
                    best = INF
                    for cl in range(3):
                        if cl == cl2:
                            continue
                        for cr in range(3):
                            if cr == cr2 or cr == cl:
                                continue
                            if dp[cl][cr] < best:
                                best = dp[cl][cr]
                    if best < INF:
                        new_dp[cl2][cr2] = best + add
            dp = new_dp

        ans = INF
        for cl in range(3):
            for cr in range(3):
                if cl != cr:
                    if dp[cl][cr] < ans:
                        ans = dp[cl][cr]
        return ans

class Solution:
    def maxFreeTime(self, eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
        n = len(startTime)
        gaps = [startTime[0]]
        for i in range(1, n):
            gaps.append(startTime[i] - endTime[i - 1])
        gaps.append(eventTime - endTime[-1])

        window = k + 1
        m = len(gaps)
        if window >= m:
            return sum(gaps)

        cur = sum(gaps[:window])
        best = cur
        for i in range(window, m):
            cur += gaps[i] - gaps[i - window]
            if cur > best:
                best = cur
        return best

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        for d in range(-(n - 1), n):
            if d >= 0:
                i, j = d, 0
            else:
                i, j = 0, -d
            elems = []
            ii, jj = i, j
            while ii < n and jj < n:
                elems.append(grid[ii][jj])
                ii += 1
                jj += 1
            if d >= 0:
                elems.sort(reverse=True)
            else:
                elems.sort()
            ii, jj = i, j
            idx = 0
            while ii < n and jj < n:
                grid[ii][jj] = elems[idx]
                idx += 1
                ii += 1
                jj += 1
        return grid

from typing import List

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        groups = {}
        for i, v in enumerate(nums):
            groups.setdefault(v, []).append(i)

        best = [-1] * n
        for v, idxs in groups.items():
            m = len(idxs)
            if m < 2:
                continue
            for k in range(m):
                i = idxs[k]
                prev_i = idxs[(k - 1) % m]
                next_i = idxs[(k + 1) % m]
                d1 = abs(i - prev_i)
                d1 = min(d1, n - d1)
                d2 = abs(i - next_i)
                d2 = min(d2, n - d2)
                best[i] = min(d1, d2)

        return [best[q] for q in queries]

