class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        cnt_k = nums.count(k)
        best_gain = 0
        for v in set(nums):
            if v == k:
                continue
            cur = 0
            mx = 0
            for x in nums:
                if x == v:
                    cur += 1
                elif x == k:
                    cur -= 1
                if cur < 0:
                    cur = 0
                if cur > mx:
                    mx = cur
            if mx > best_gain:
                best_gain = mx
        return cnt_k + best_gain

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n_cnt = s_cnt = e_cnt = w_cnt = 0
        best = 0
        for i, ch in enumerate(s):
            if ch == 'N':
                n_cnt += 1
            elif ch == 'S':
                s_cnt += 1
            elif ch == 'E':
                e_cnt += 1
            else:
                w_cnt += 1
            total = i + 1
            base = abs(n_cnt - s_cnt) + abs(e_cnt - w_cnt)
            best = max(best, min(total, base + 2 * k))
        return best

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        M = max(groups)
        best = [-1] * (M + 1)
        seen = set()
        for j, e in enumerate(elements):
            if e in seen:
                continue
            seen.add(e)
            if e > M:
                continue
            for m in range(e, M + 1, e):
                if best[m] == -1:
                    best[m] = j
        return [best[g] for g in groups]

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        total = sum(l * l for _, _, l in squares)
        target = total / 2.0

        def below(y):
            s = 0.0
            for _, yi, l in squares:
                if y <= yi:
                    continue
                if y >= yi + l:
                    s += l * l
                else:
                    s += l * (y - yi)
            return s

        lo = min(yi for _, yi, _ in squares)
        hi = max(yi + l for _, yi, l in squares)

        for _ in range(100):
            mid = (lo + hi) / 2.0
            if below(mid) < target:
                lo = mid
            else:
                hi = mid
        return lo

