class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []
        for i, row in enumerate(grid):
            if limits[i] > 0:
                top = heapq.nlargest(limits[i], row)
                candidates.extend(top)
        candidates.sort(reverse=True)
        return sum(candidates[:k])

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        first = {}
        last = {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i

        intervals = []
        for i in range(n):
            if first[s[i]] != i:
                continue
            j = last[s[i]]
            valid = True
            p = i
            while p <= j:
                c = s[p]
                if first[c] < i:
                    valid = False
                    break
                if last[c] > j:
                    j = last[c]
                p += 1
            if not valid:
                continue
            if i == 0 and j == n - 1:
                continue
            intervals.append((i, j))

        intervals.sort(key=lambda x: x[1])
        count = 0
        prev_end = -1
        for start, end in intervals:
            if start > prev_end:
                count += 1
                prev_end = end

        return count >= k

from functools import lru_cache
from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums)

        @lru_cache(maxsize=None)
        def dp(i: int, c: int) -> int:
            # Remaining elements (in order): nums[c], nums[i], nums[i+1], ..., nums[n-1]
            if n - i + 1 < 3:
                m = nums[c]
                for j in range(i, n):
                    if nums[j] > m:
                        m = nums[j]
                return m
            a, b, d = nums[c], nums[i], nums[i + 1]
            return min(
                max(a, b) + dp(i + 2, i + 1),
                max(a, d) + dp(i + 2, i),
                max(b, d) + dp(i + 2, c),
            )

        return dp(1, 0)

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        n = len(original)
        lo = -float('inf')
        hi = float('inf')
        for i in range(n):
            diff = original[i] - original[0]
            lo = max(lo, bounds[i][0] - diff)
            hi = min(hi, bounds[i][1] - diff)
        return max(0, hi - lo + 1)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def cost(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def solve(i, j, r):
            if i > j:
                return 0
            if i == j:
                return 1
            best = max(solve(i + 1, j, r), solve(i, j - 1, r))
            c = cost(s[i], s[j])
            if c <= r:
                if i + 1 > j - 1:
                    best = max(best, 2)
                else:
                    best = max(best, 2 + solve(i + 1, j - 1, r - c))
            return best

        result = solve(0, n - 1, k)
        solve.cache_clear()
        return result

from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        if n == 0:
            return len(fruits)
        size = 1
        while size < n:
            size <<= 1
        tree = [0] * (2 * size)
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def place(q):
            if tree[1] < q:
                return False
            node = 1
            node_l, node_r = 0, size - 1
            while node_l != node_r:
                mid = (node_l + node_r) // 2
                if tree[2 * node] >= q:
                    node = 2 * node
                    node_r = mid
                else:
                    node = 2 * node + 1
                    node_l = mid + 1
            tree[node] = -1
            node >>= 1
            while node:
                new_val = max(tree[2 * node], tree[2 * node + 1])
                if tree[node] == new_val:
                    break
                tree[node] = new_val
                node >>= 1
            return True

        unplaced = 0
        for q in fruits:
            if not place(q):
                unplaced += 1
        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def is_pal(x: str) -> bool:
            return x == x[::-1]

        best = 0

        # Case: substring from only one of the strings (the other is empty)
        for st in (s, t):
            n = len(st)
            for i in range(n):
                for j in range(i, n):
                    sub = st[i:j+1]
                    if is_pal(sub):
                        if len(sub) > best:
                            best = len(sub)

        # Case: nonempty substring from both s and t, concatenated
        ns, nt = len(s), len(t)
        for i in range(ns):
            for j in range(i, ns):
                a = s[i:j+1]
                for k in range(nt):
                    for l in range(k, nt):
                        b = t[k:l+1]
                        c = a + b
                        if is_pal(c) and len(c) > best:
                            best = len(c)

        return best

from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + skill[i]

        S = 0
        for j in range(m - 1):
            mj = mana[j]
            mj1 = mana[j + 1]
            best = 0
            for i in range(n):
                diff = prefix[i + 1] * mj - prefix[i] * mj1
                if diff > best:
                    best = diff
            S += best

        return S + prefix[n] * mana[-1]

from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        m = len(queries)

        def feasible(k: int) -> bool:
            for i in range(n):
                target = nums[i]
                if target == 0:
                    continue
                reachable = 1  # bit 0 represents sum 0
                target_bit = 1 << target
                for j in range(k):
                    l, r, v = queries[j]
                    if l <= i <= r:
                        reachable |= reachable << v
                        if reachable & target_bit:
                            break
                if not (reachable & target_bit):
                    return False
            return True

        # If even using all queries we cannot achieve zero array, return -1
        if not feasible(m):
            return -1

        lo, hi = 0, m
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        ones_count = s.count('1')

        # Collect lengths of consecutive 0-runs in order
        zero_runs = []
        i = 0
        while i < n:
            if s[i] == '0':
                j = i
                while j < n and s[j] == '0':
                    j += 1
                zero_runs.append(j - i)
                i = j
            else:
                i += 1

        if len(zero_runs) < 2:
            return ones_count

        best_gain = 0
        for k in range(len(zero_runs) - 1):
            best_gain = max(best_gain, zero_runs[k] + zero_runs[k + 1])

        return ones_count + best_gain

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(p) for p in properties]

        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return len(set(find(i) for i in range(n)))

