import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    idx = 0
    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1
    grid = []
    for _ in range(H):
        grid.append(data[idx].decode()); idx += 1
    A = int(data[idx]) - 1; idx += 1
    B = int(data[idx]) - 1; idx += 1
    C = int(data[idx]) - 1; idx += 1
    D = int(data[idx]) - 1; idx += 1

    INF = 10**9
    N = H * W
    dist = [INF] * N
    seen = [False] * N
    s = A * W + B
    t = C * W + D
    dist[s] = 0
    dq = deque([s])

    while dq:
        p = dq.popleft()
        if seen[p]:
            continue
        seen[p] = True
        if p == t:
            break
        r, c = divmod(p, W)
        d = dist[p]
        nd = d + 1
        # 0-weight: adjacent original road cells
        if r > 0:
            np = p - W
            if not seen[np] and grid[r-1][c] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        if r < H - 1:
            np = p + W
            if not seen[np] and grid[r+1][c] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        if c > 0:
            np = p - 1
            if not seen[np] and grid[r][c-1] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        if c < W - 1:
            np = p + 1
            if not seen[np] and grid[r][c+1] == '.' and dist[np] > d:
                dist[np] = d
                dq.appendleft(np)
        # 1-weight: kick up to 2 cells in any cardinal direction
        if r > 0:
            np = p - W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if r > 1:
            np = p - 2 * W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if r < H - 1:
            np = p + W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if r < H - 2:
            np = p + 2 * W
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c > 0:
            np = p - 1
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c > 1:
            np = p - 2
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c < W - 1:
            np = p + 1
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)
        if c < W - 2:
            np = p + 2
            if not seen[np] and dist[np] > nd:
                dist[np] = nd
                dq.append(np)

    print(dist[t])

main()

import sys

def solve():
    data = sys.stdin.read().split()
    N = int(data[0])
    A = [int(x) for x in data[1:N+1]]

    # b[i] in {0,1} for i in 0..N-1 (cyclic).
    # b[i] = 1 means a triple (ARC or CRA) is placed at positions (i, i+1, i+2),
    # which sets A[i] and A[i+1] to 1.
    # Constraints:
    # - b[i] * b[(i+1) % N] == 0 (R cannot be in both positions i+1 and i+2)
    # - If A[i] == 0: b[(i-1) % N] + b[i] >= 1 (coverage)

    for b0 in (0, 1):
        for b1 in (0, 1):
            if b0 & b1:
                continue
            # Coverage check for A[1]
            if N >= 2 and A[1] == 0 and (b0 + b1) < 1:
                continue
            # DP from i=2 to N-1; state = (b[i-2], b[i-1]); bn = b[i]
            states = {(b0, b1)}
            ok = True
            for i in range(2, N):
                ai = A[i]
                new_states = set()
                for (bp, bc) in states:
                    for bn in (0, 1):
                        if bc & bn:
                            continue
                        if ai == 0 and (bc + bn) < 1:
                            continue
                        new_states.add((bc, bn))
                states = new_states
                if not states:
                    ok = False
                    break
            if not ok:
                continue
            # Wraparound: state is (b[N-2], b[N-1]); check against b[0]
            for (bp, bc) in states:
                if bc & b0:
                    continue
                if A[0] == 0 and (bc + b0) < 1:
                    continue
                print("Yes")
                return
    print("No")

solve()

class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            mirror_idx = 25 - idx

            if stacks[mirror_idx]:
                j = stacks[mirror_idx].pop()
                score += i - j
            else:
                stacks[idx].append(i)

        return score

from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = -10**15

        prev = [[NEG_INF] * 3 for _ in range(n)]

        for i in range(m):
            curr = [[NEG_INF] * 3 for _ in range(n)]

            for j in range(n):
                val = coins[i][j]

                if i == 0 and j == 0:
                    curr[j][0] = val
                    if val < 0:
                        curr[j][1] = 0
                    continue

                for used in range(3):
                    best_prev = NEG_INF

                    if i > 0:
                        best_prev = max(best_prev, prev[j][used])
                    if j > 0:
                        best_prev = max(best_prev, curr[j - 1][used])

                    if best_prev != NEG_INF:
                        curr[j][used] = max(curr[j][used], best_prev + val)

                    if val < 0 and used > 0:
                        best_prev = NEG_INF

                        if i > 0:
                            best_prev = max(best_prev, prev[j][used - 1])
                        if j > 0:
                            best_prev = max(best_prev, curr[j - 1][used - 1])

                        if best_prev != NEG_INF:
                            curr[j][used] = max(curr[j][used], best_prev)

            prev = curr

        return max(prev[n - 1])

