import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        inf = 10**18
        dist = [inf] * n
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            cur, node = heapq.heappop(pq)
            if cur != dist[node]:
                continue

            for nxt, w in rev[node]:
                cost = max(cur, w)
                if cost < dist[nxt]:
                    dist[nxt] = cost
                    heapq.heappush(pq, (cost, nxt))

        ans = max(dist)
        return -1 if ans == inf else ans

from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for event_type, timestamp_str, value in events:
            t = int(timestamp_str)

            if event_type == "OFFLINE":
                user_id = int(value)
                offline_until[user_id] = t + 60
            elif value == "ALL":
                for user_id in range(numberOfUsers):
                    mentions[user_id] += 1
            elif value == "HERE":
                for user_id in range(numberOfUsers):
                    if offline_until[user_id] <= t:
                        mentions[user_id] += 1
            else:
                for token in value.split():
                    user_id = int(token[2:])
                    mentions[user_id] += 1

        return mentions

from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)

        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        neg_inf = float("-inf")
        prev = [0] * (n + 1)

        for _ in range(k):
            curr = [neg_inf] * (n + 1)
            best = neg_inf

            for i in range(1, n + 1):
                if i >= m and prev[i - m] != neg_inf:
                    best = max(best, prev[i - m] - prefix[i - m])

                curr[i] = curr[i - 1]

                if best != neg_inf:
                    curr[i] = max(curr[i], prefix[i] + best)

            prev = curr

        return prev[n]

from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**18
        half = n // 2

        dp = [[INF] * 3 for _ in range(3)]

        for left_color in range(3):
            for right_color in range(3):
                if left_color != right_color:
                    dp[left_color][right_color] = cost[0][left_color] + cost[n - 1][right_color]

        for i in range(1, half):
            new_dp = [[INF] * 3 for _ in range(3)]

            for prev_left in range(3):
                for prev_right in range(3):
                    if dp[prev_left][prev_right] == INF:
                        continue

                    for left_color in range(3):
                        if left_color == prev_left:
                            continue

                        for right_color in range(3):
                            if right_color == prev_right or right_color == left_color:
                                continue

                            new_dp[left_color][right_color] = min(
                                new_dp[left_color][right_color],
                                dp[prev_left][prev_right]
                                + cost[i][left_color]
                                + cost[n - 1 - i][right_color],
                            )

            dp = new_dp

        return min(min(row) for row in dp)

from typing import List
from collections import defaultdict

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        positions = defaultdict(list)

        for i, value in enumerate(nums):
            positions[value].append(i)

        nearest = [-1] * n

        for idxs in positions.values():
            k = len(idxs)
            if k == 1:
                continue

            for t, idx in enumerate(idxs):
                prev_idx = idxs[(t - 1) % k]
                next_idx = idxs[(t + 1) % k]

                dist_prev = (idx - prev_idx) % n
                dist_next = (next_idx - idx) % n

                nearest[idx] = min(dist_prev, dist_next)

        return [nearest[q] for q in queries]

from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        best_gain = 0

        for target in range(1, 51):
            if target == k:
                continue

            cur = 0
            for num in nums:
                if num == target:
                    cur += 1
                elif num == k:
                    cur -= 1

                cur = max(cur, 0)
                best_gain = max(best_gain, cur)

        return base + best_gain

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        count = {'N': 0, 'S': 0, 'E': 0, 'W': 0}
        ans = 0

        for i, ch in enumerate(s):
            count[ch] += 1
            steps = i + 1

            bad_counts = (
                count['S'] + count['W'],
                count['S'] + count['E'],
                count['N'] + count['W'],
                count['N'] + count['E'],
            )

            for bad in bad_counts:
                ans = max(ans, steps - 2 * max(0, bad - k))

        return ans

from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        INF = 10**9

        first_idx = [INF] * (max_group + 1)

        for i, x in enumerate(elements):
            if x <= max_group and first_idx[x] == INF:
                first_idx[x] = i

        best = [INF] * (max_group + 1)

        for x in range(1, max_group + 1):
            idx = first_idx[x]
            if idx == INF:
                continue

            for multiple in range(x, max_group + 1, x):
                if idx < best[multiple]:
                    best[multiple] = idx

        return [-1 if best[g] == INF else best[g] for g in groups]

from typing import List

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        events = []
        total_area = 0

        for _, y, l in squares:
            total_area += l * l
            events.append((y, l))
            events.append((y + l, -l))

        events.sort()
        target = total_area / 2

        area = 0.0
        active_width = 0
        prev_y = events[0][0]
        i = 0

        while i < len(events):
            y = events[i][0]

            if y > prev_y:
                next_area = area + active_width * (y - prev_y)

                if next_area >= target:
                    return prev_y + (target - area) / active_width

                area = next_area
                prev_y = y

            while i < len(events) and events[i][0] == y:
                active_width += events[i][1]
                i += 1

            if area == target:
                return float(y)

        return float(prev_y)

