class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []

        for row, limit in zip(grid, limits):
            candidates.extend(sorted(row, reverse=True)[:limit])

        candidates.sort(reverse=True)
        return sum(candidates[:k])

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        first = [n] * 26
        last = [-1] * 26

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            first[idx] = min(first[idx], i)
            last[idx] = i

        intervals = []

        for c in range(26):
            if first[c] == n:
                continue

            start = first[c]
            end = last[c]
            valid = True
            i = start

            while i <= end:
                x = ord(s[i]) - ord('a')
                if first[x] < start:
                    valid = False
                    break
                end = max(end, last[x])
                i += 1

            if valid and not (start == 0 and end == n - 1):
                intervals.append((end, start))

        intervals.sort()

        count = 0
        prev_end = -1

        for end, start in intervals:
            if start > prev_end:
                count += 1
                prev_end = end
                if count >= k:
                    return True

        return False

from typing import List

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 2:
            return max(nums)

        dp = {
            0: max(nums[1], nums[2]),
            1: max(nums[0], nums[2]),
            2: max(nums[0], nums[1]),
        }

        i = 3
        while i + 1 < n:
            new_dp = {}

            for survivor, cost in dp.items():
                a = nums[survivor]
                b = nums[i]
                c = nums[i + 1]

                transitions = (
                    (survivor, cost + max(b, c)),
                    (i, cost + max(a, c)),
                    (i + 1, cost + max(a, b)),
                )

                for next_survivor, next_cost in transitions:
                    if next_cost < new_dp.get(next_survivor, float("inf")):
                        new_dp[next_survivor] = next_cost

            dp = new_dp
            i += 2

        ans = float("inf")
        for survivor, cost in dp.items():
            if i < n:
                ans = min(ans, cost + max(nums[survivor], nums[i]))
            else:
                ans = min(ans, cost + nums[survivor])

        return ans

from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        low = -10**18
        high = 10**18

        for x, (u, v) in zip(original, bounds):
            low = max(low, u - x)
            high = min(high, v - x)

        return max(0, high - low + 1)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        vals = [ord(c) - ord('a') for c in s]

        dp = [[None] * n for _ in range(n)]

        for i in range(n):
            dp[i][i] = bytearray([1] * (k + 1))

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1

                diff = abs(vals[i] - vals[j])
                cost = min(diff, 26 - diff)

                left = dp[i + 1][j]
                right = dp[i][j - 1]
                inner = dp[i + 1][j - 1] if length > 2 else None

                cur = bytearray(k + 1)

                for budget in range(k + 1):
                    best = max(left[budget], right[budget])

                    if budget >= cost:
                        paired = 2
                        if inner is not None:
                            paired += inner[budget - cost]
                        best = max(best, paired)

                    cur[budget] = best

                dp[i][j] = cur

        return dp[0][n - 1][k]

from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)

        size = 1
        while size < n:
            size *= 2

        seg = [0] * (2 * size)

        for i, cap in enumerate(baskets):
            seg[size + i] = cap

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        unplaced = 0

        for fruit in fruits:
            if seg[1] < fruit:
                unplaced += 1
                continue

            idx = 1
            while idx < size:
                left = 2 * idx
                if seg[left] >= fruit:
                    idx = left
                else:
                    idx = left + 1

            seg[idx] = 0
            idx //= 2

            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx //= 2

        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def substrings(x: str):
            res = [""]
            for i in range(len(x)):
                for j in range(i + 1, len(x) + 1):
                    res.append(x[i:j])
            return res

        parts_s = substrings(s)
        parts_t = substrings(t)

        ans = 0
        for a in parts_s:
            for b in parts_t:
                candidate = a + b
                if len(candidate) > ans and candidate == candidate[::-1]:
                    ans = len(candidate)

        return ans

from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)

        prefix = [0] * (n + 1)
        for i, s in enumerate(skill):
            prefix[i + 1] = prefix[i] + s

        start = 0
        for j in range(1, len(mana)):
            prev_mana = mana[j - 1]
            curr_mana = mana[j]

            delay = 0
            for i in range(n):
                delay = max(
                    delay,
                    prev_mana * prefix[i + 1] - curr_mana * prefix[i]
                )

            start += delay

        return start + mana[-1] * prefix[n]

from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        if all(x == 0 for x in nums):
            return 0

        dp = [1] * n
        masks = [(1 << (target + 1)) - 1 for target in nums]

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                dp[i] |= dp[i] << val
                dp[i] &= masks[i]

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k

        return -1

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        t = '1' + s + '1'

        runs = []
        i = 0
        while i < len(t):
            j = i
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        for i in range(1, len(runs) - 1):
            if runs[i][0] == '1' and runs[i - 1][0] == '0' and runs[i + 1][0] == '0':
                best_gain = max(best_gain, runs[i - 1][1] + runs[i + 1][1])

        return ones + best_gain

from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(row) for row in properties]

        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            root_a = find(a)
            root_b = find(b)

            if root_a == root_b:
                return

            if rank[root_a] < rank[root_b]:
                parent[root_a] = root_b
            elif rank[root_a] > rank[root_b]:
                parent[root_b] = root_a
            else:
                parent[root_b] = root_a
                rank[root_a] += 1

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i].intersection(sets[j])) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})

import sys

def count_snake_upto(n: int) -> int:
    if n < 10:
        return 0

    s = str(n)
    m = len(s)
    ans = 0

    for length in range(2, m):
        for first in range(1, 10):
            ans += first ** (length - 1)

    first_digit = int(s[0])

    for first in range(1, first_digit):
        ans += first ** (m - 1)

    first = first_digit
    for i in range(1, m):
        cur = int(s[i])
        remaining = m - i - 1

        ans += min(cur, first) * (first ** remaining)

        if cur >= first:
            break
    else:
        ans += 1

    return ans

def main():
    L, R = map(int, sys.stdin.readline().split())
    print(count_snake_upto(R) - count_snake_upto(L - 1))

if __name__ == "__main__":
    main()

