    main()

import sys

def solve():
    input = sys.stdin.buffer.readline
    T = int(input())
    ans = []

    for _ in range(T):
        N = int(input())
        A = list(map(int, input().split()))

        adjacent_same = [False] * (N + 1)
        for i in range(2 * N - 1):
            if A[i] == A[i + 1]:
                adjacent_same[A[i]] = True

        first_pos = {}
        counted = set()
        total = 0

        for i in range(2 * N - 1):
            x, y = A[i], A[i + 1]
            if x == y:
                continue
            if x > y:
                x, y = y, x

            key = (x, y)
            if key not in first_pos:
                first_pos[key] = i
            elif key not in counted and first_pos[key] + 1 < i:
                if not adjacent_same[x] and not adjacent_same[y]:
                    counted.add(key)
                    total += 1

        ans.append(str(total))

    print("\n".join(ans))

if __name__ == "__main__":
    solve()

import sys
import heapq

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    S = input().strip()
    T = input().strip()

    cnt = [0] * 10
    for ch in T:
        cnt[ord(ch) - 48] += 1

    ans = list(S)
    used_last = False
    last = ord(T[-1]) - 48

    heap = []
    for i, ch in enumerate(ans):
        heapq.heappush(heap, (ord(ch) - 48, i))

    for d in range(9, 0, -1):
        while cnt[d] and heap and heap[0][0] < d:
            _, i = heapq.heappop(heap)
            ans[i] = str(d)
            heapq.heappush(heap, (d, i))
            cnt[d] -= 1
            if d == last:
                used_last = True

    if not used_last:
        best_i = -1
        for i, ch in enumerate(ans):
            if ord(ch) - 48 <= last:
                best_i = i
                break

        if best_i != -1:
            ans[best_i] = str(last)

    print(''.join(ans))

if __name__ == "__main__":
    solve()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:]

    special = (n % 4 == 2)

    for start in (0, 1):
        if not special:
            possible = {start}

            for i in range(n):
                nxt = set()
                for prev in possible:
                    for cur in (0, 1):
                        if i == n - 1 and cur != start:
                            continue

                        if a[i] == 0:
                            if prev ^ cur:
                                nxt.add(cur)
                        else:
                            if not (prev and cur):
                                nxt.add(cur)

                possible = nxt
                if not possible:
                    break

            if possible:
                print("Yes")
                return

        else:
            states = {(start, False, False)}

            for i in range(n):
                nxt = set()
                even_target = 1 if i % 2 == 0 else 0
                odd_target = 1 - even_target

                for prev, diff_even, diff_odd in states:
                    for cur in (0, 1):
                        if i == n - 1 and cur != start:
                            continue

                        if a[i] == 0:
                            ok = (prev ^ cur) == 1
                        else:
                            ok = not (prev and cur)

                        if ok:
                            nxt.add((
                                cur,
                                diff_even or cur != even_target,
                                diff_odd or cur != odd_target
                            ))

                states = nxt
                if not states:
                    break

            if any(diff_even and diff_odd for _, diff_even, diff_odd in states):
                print("Yes")
                return

    print("No")

if __name__ == "__main__":
    solve()

import sys

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0])
    M = int(data[1])
    A = data[2:2 + N]
    B = data[2 + N:2 + N + M]

    left = [-1] * M
    j = 0
    for i, x in enumerate(A):
        if j < M and x == B[j]:
            left[j] = i
            j += 1

    if j < M:
        print("No")
        return

    right = [-1] * M
    j = M - 1
    for i in range(N - 1, -1, -1):
        if j >= 0 and A[i] == B[j]:
            right[j] = i
            j -= 1

    for l, r in zip(left, right):
        if l < r:
            print("Yes")
            return

    print("No")

if __name__ == "__main__":
    main()
